INSERT INTO user_tag_preference (user_id, tag_id, score)
SELECT #{userId}, tag_id, #{delta}
FROM content_tag
WHERE content_id = #{contentId}
ORDER BY tag_id
ON DUPLICATE KEY UPDATE score = user_tag_preference.score + #{delta}

